    spyCopySync = jest.spyOn(fs, 'cpSync');
    spyCopySync.mockImplementation(() => undefined);
  });

  afterEach(() => {
    jest.resetAllMocks();
    jest.clearAllMocks();
    jest.restoreAllMocks();
  });

